import { useEffect, useState } from "react";
import api from "../api";
import CodeEditor from "./CodeEditor";
import LevelsSidebar from "./LevelsSidebar";

export default function App() {
const userId = localStorage.getItem("userId");
const [sample, setSample] = useState(null);

  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(1);
  const [level, setLevel] = useState(null);

  const [language, setLanguage] = useState("python");

  const [code, setCode] = useState("");
  const [input, setInput] = useState("");
  const [output, setOutput] = useState("");
  const [error, setError] = useState("");

  const [sidebarOpen, setSidebarOpen] = useState(false);

  /* 🔹 Load levels sidebar */
  useEffect(() => {
    api
      .get(`/levels/${userId}`)
      .then((res) => {
        setLevels(res.data.levels);
        setCurrentLevel(res.data.currentLevel);
      })
      .catch(() => setError("Failed to load levels"));
  }, []);

  /* 🔹 Load current level */
  useEffect(() => {
    api
      .get(`/level/${userId}`)
      .then((res) => {
        setLevel(res.data.level);
        setSample(res.data.sample); 
        setCode("");
        setInput("");
        setOutput("");
      })
      .catch(() => setError("Failed to load level"));
  }, [currentLevel]);

  if (error) return <h2 style={{ padding: 20 }}>{error}</h2>;
  if (!level) return <h2 style={{ padding: 20 }}>Loading...</h2>;

  return (
    <div style={styles.page}>
      {/* ✅ Top Navbar */}
      <div style={styles.navbar}>
        <button
          style={styles.menuBtn}
          onClick={() => setSidebarOpen((prev) => !prev)}
        >
          ☰
        </button>
        <h1 style={styles.logo}>Dailycode</h1>

        <div style={styles.langBox}>
          <span style={styles.langLabel}>Language:</span>
          <select
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            style={styles.select}
          >
            <option value="python">Python</option>
            <option value="javascript">JavaScript</option>
            <option value="c">C</option>
            <option value="cpp">C++</option>
          </select>
        </div>
      </div>

      <div style={styles.layout}>
        {/* ✅ SIDEBAR */}
        <div
          style={{
            ...styles.sidebar,
            ...(sidebarOpen ? styles.sidebarOpen : {}),
          }}
        >
          <div style={styles.sidebarHeader}>
            <h3 style={{ margin: 0 }}></h3>
            <button
              style={styles.closeBtn}
              onClick={() => setSidebarOpen(false)}
            >
              ✖
            </button>
          </div>

          <LevelsSidebar
            levels={levels}
            currentLevel={currentLevel}
            onSelectLevel={(lvl) => {
              if (lvl <= currentLevel) {
                setCurrentLevel(lvl);
                setSidebarOpen(false); // ✅ auto close on mobile
              }
            }}
          />
        </div>

        {/* ✅ MAIN AREA */}
        <div style={styles.main}>
          {/* ✅ Problem Card */}
          <div style={styles.card}>
            <div style={styles.cardHeader}>
              <h2 style={styles.title}>
                Level {level.level_no}: {level.title}
              </h2>
              <span style={styles.badge}>Unlocked ✅</span>
            </div>
            <p style={styles.desc}>{level.description}</p>
          </div>

          {/* ✅ Editor Card */}
          <div style={styles.editorCard}>
            <div style={styles.editorHeader}>
              <h3 style={{ margin: 0 }}>Editor</h3>

              <div style={styles.btnRow}>
                <button
                  style={{ ...styles.btn, ...styles.runBtn }}
                  onClick={async () => {
                    if (!input.trim()) {
                      alert("Input required for Run");
                      return;
                    }
                    const res = await api.post("/run", {
                      code,
                      language,
                      input,
                    });
                    setOutput(res.data.output);
                  }}
                >
                  ▶ Run
                </button>

                <button
                  style={{ ...styles.btn, ...styles.submitBtn }}
                  onClick={async () => {
                    const res = await api.post("/submit", {
                      userId,
                      code,
                      language,
                    });

                    alert(res.data.verdict);

                    if (res.data.verdict.includes("Accepted")) {
                      setCurrentLevel((prev) => prev + 1);
                    }
                  }}
                >
                  ✔ Submit
                </button>
              </div>
            </div>

            <div style={styles.editorBody}>
              <div style={styles.editorBox}>
                <CodeEditor code={code} setCode={setCode} />
              </div>
            </div>
          </div>

          {/* ✅ IO Section */}
          <div style={styles.ioGrid}>
            {/* Input */}
            <div style={styles.ioCard}>
              <h4 style={styles.ioTitle}>Your Input (Run only)</h4>
              <textarea
                style={styles.textarea}
                rows={6}
                value={input}
                placeholder="Enter your input here..."
                onChange={(e) => setInput(e.target.value)}
              />
            </div>

            {/* Output */}
            <div style={styles.ioCard}>
              <h4 style={styles.ioTitle}>Your Output</h4>
              <pre style={styles.outputBox}>
                {output || "Output will appear here..."}
              </pre>
            </div>
          </div>
        </div>
      </div>

      {/* ✅ Mobile background overlay */}
      {sidebarOpen && (
        <div
          style={styles.overlay}
          onClick={() => setSidebarOpen(false)}
        ></div>
      )}
    </div>
  );
}

/* ✅ CSS-IN-JS Modern UI */
const styles = {
  page: {
    background: "#0f172a",
    color: "#f1f5f9",
    minHeight: "100vh",
    fontFamily: "Inter, sans-serif",
  },

  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "#1e293b",
    padding: "10px 20px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.4)",
  },

  menuBtn: {
    background: "transparent",
    color: "white",
    border: "none",
    fontSize: 22,
    cursor: "pointer",
    display: "none",
  },


  logo: { fontSize: "1.5rem",
     fontWeight: "bold",
      color: "#38bdf8" },

  langBox: {
    display: "flex",
    alignItems: "center",
    gap: 8,
    color: "#38bdf8" 
  },

  langLabel: {
    fontSize: 14,
    opacity: 0.9,
  },

  select: {
    padding: "6px 10px",
    borderRadius: 8,
    border: "1px solid #374151",
    background: "#1f2937",
    color: "white",
    outline: "none",
    cursor: "pointer",
  },

  layout: {
    display: "flex",
    height: "calc(100vh - 60px)",
        background: "#0f172a",
  },

  sidebar: {
    width: 280,

    borderRight: "1px solid #e5e7eb",
    padding: 12,
    overflowY: "auto",
    background: "#0f172a",
  },

  sidebarHeader: {
    display: "flex",
